application.javascript:
const form = document.getElementById('booking-form');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('confirmation');
const count = document.getElementById('booking-count');
const dateInput = document.getElementById('date');
let bookings = [];

function localDateString(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}
dateInput.min = localDateString(new Date());

function formatDate(value) {
  return new Date(`${value}T00:00:00`).toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'});
}
function formatTime(value) {
  return new Date(`2000-01-01T${value}`).toLocaleTimeString(undefined, {hour:'numeric', minute:'2-digit'});
}
function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = bookings.filter(item => !item.cancelled).length;
  bookings.forEach(item => {
    const card = document.createElement('article');
    card.className = `booking${item.cancelled ? ' cancelled' : ''}`;
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    const main = document.createElement('div');
    main.className = 'booking-main';
    main.innerHTML = `<div class="booking-type">${item.type}</div><h3 class="booking-name" data-testid="booking-name-display"></h3><p class="booking-meta">${formatDate(item.date)} · ${formatTime(item.time)}</p><p class="booking-meta">${item.email}</p>`;
    main.querySelector('[data-testid="booking-name-display"]').textContent = item.name;
    card.appendChild(main);
    if (item.cancelled) {
      const label = document.createElement('span'); label.className = 'cancelled-label'; label.textContent = 'Cancelled'; card.appendChild(label);
    } else {
      const button = document.createElement('button'); button.type = 'button'; button.className = 'cancel-button'; button.dataset.testid = 'booking-cancel'; button.textContent = 'Cancel';
      button.addEventListener('click', () => { item.cancelled = true; render(); }); card.appendChild(button);
    }
    list.appendChild(card);
  });
}
form.addEventListener('submit', event => {
  event.preventDefault();
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = new FormData(form);
  const item = {name:data.get('name').trim(), email:data.get('email'), date:data.get('date'), time:data.get('time'), type:data.get('type'), cancelled:false};
  if (item.date < localDateString(new Date())) { dateInput.setCustomValidity('Please choose today or a future date.'); dateInput.reportValidity(); dateInput.setCustomValidity(''); return; }
  bookings.push(item); render();
  confirmation.textContent = `Booking confirmed for ${item.name} on ${formatDate(item.date)}.`;
  confirmation.hidden = false;
  form.reset(); dateInput.min = localDateString(new Date());
  window.setTimeout(() => { confirmation.hidden = true; }, 5000);
});
render();
